14	 */
15	export function getNormalizedRelativePath(
16	  projectRoot: string,
17	  filePath: string,
18	  isDirectory: boolean,
19	): string | null {
20	  if (!filePath || typeof filePath !== 'string') {
21	    return null;
22	  }
23	
24	  const absoluteFilePath = path.resolve(projectRoot, filePath);
25	
26	  // Ensure the path is within the project root
27	  if (!isWithinRoot(absoluteFilePath, projectRoot)) {
28	    return null;
29	  }
30	
31	  const relativePath = path.relative(projectRoot, absoluteFilePath);
32	
33	  // Convert Windows backslashes to forward slashes for the 'ignore' library
34	  let normalized = relativePath.replace(/\\/g, '/');
35	
36	  // Preserve trailing slash to ensure directory patterns (e.g., 'dist/') match correctly
37	  if (isDirectory && !normalized.endsWith('/') && normalized !== '') {
38	    normalized += '/';
39	  }
40	
41	  // Handle the project root directory
42	  if (normalized === '') {
43	    return isDirectory ? '/' : '';
44	  }
45	
46	  // Ensure relative paths don't start with a slash unless it represents the root
47	  if (normalized.startsWith('/') && normalized !== '/') {
48	    normalized = normalized.substring(1);
49	  }
50	
51	  return normalized;
